message.content:
[
  {
    "ae_welfare_concern": "There are five people on that track, and I know how much that matters.",
    "pd_decision_conflict": "Deciding this alone feels like too much",
    "pd_personal_consequence_anxiety": "scared I'd be the one hauled in afterward for tampering"
  },
  {
    "pd_decision_conflict": "It's a miserable spot to be in.",
    "pd_personal_consequence_anxiety": "interfering with public infrastructure frightens me more than I can easily say."
  },
  {
    "ce_understood_harm": "Five workers, a train rolling. I know what's at stake.",
    "pd_decision_conflict": "Oh, this sits heavy.",
    "pd_personal_consequence_anxiety": "My stomach knots just picturing someone asking why I touched the controls."
  },
  {
    "pd_decision_conflict": "I'm not ready to commit, and I wish I were braver about it.",
    "pd_personal_consequence_anxiety": "Part of me is dreading the questions afterward, the forms, maybe losing my job"
  },
  {
    "pd_decision_conflict": "It's a lonely, grim feeling, standing there.",
    "pd_personal_consequence_anxiety": "If I pull that lever and something about the procedure was wrong, I could lose my license"
  },
  {
    "pd_decision_conflict": "I hate that I can't just give you a clean answer.",
    "pd_personal_consequence_anxiety": "I keep imagining my face on the news, people arguing about whether I had any right."
  },
  {
    "ce_understood_harm": "Five workers down there. I understand how serious it is.",
    "pd_personal_consequence_anxiety": "I'm terrified of being the one they point at afterward"
  },
  {
    "pd_decision_conflict": "I'm not proud of that at all.",
    "pd_personal_consequence_anxiety": "There's also a nagging fear of fines or some kind of charge."
  },
  {
    "pd_decision_conflict": "This is the kind of moment I'd lie awake over for weeks.",
    "pd_personal_consequence_anxiety": "I'm afraid, plainly afraid, of being blamed or sued"
  },
  {
    "pd_decision_conflict": "Everything about this feels so heavy.",
    "pd_personal_consequence_anxiety": "scared stiff that the company would come after me, that I'd end up owing money"
  }
]
